class DashboardPageElement extends BaseComponent {
  private isLoading = true;
  private summary: DashboardSummary | null = null;
  private widgets: { id: string; type: 'bar' | 'line' | 'area'; metrics: string[] }[] = [
    { id: 'widget-0', type: 'bar', metrics: ['Impressions', 'Clicks', 'Spend', 'Installs'] }
  ];
  private currentPeriod: DateRange = DateRange.fromPeriodOption('7d');
  private isSidebarOpen = false;
  private activeShortcut: 'DAY' | 'EXCHANGE' | 'OS' | 'CAMPAIGN' | 'CREATIVE' | null = null;
  private isCompareDropdownOpen = false;
  private isCompareModeOpen = false;
  private compareModeSelection = '';

  constructor() {
    super();
    injectGlobalTokens(this.shadow);
    injectStyles(this.shadow, STYLES);
  }

  protected onMount(): void {
    this.shadow.addEventListener('period-changed', this.handlePeriodChanged);
    this.shadow.addEventListener('metrics-changed', this.handleMetricsChanged);
    this.shadow.addEventListener('click', this.handleClick);
    this.shadow.addEventListener('sidebar-closed', this.handleSidebarClosed);
    this.addEventListener('suggestion-accepted', this.handleSuggestionAccepted);
    void this.loadSummary();
  }

  protected onUnmount(): void {
    this.shadow.removeEventListener('period-changed', this.handlePeriodChanged);
    this.shadow.removeEventListener('metrics-changed', this.handleMetricsChanged);
    this.shadow.removeEventListener('click', this.handleClick);
    this.shadow.removeEventListener('sidebar-closed', this.handleSidebarClosed);
    this.removeEventListener('suggestion-accepted', this.handleSuggestionAccepted);
  }

  private handleSidebarClosed = (): void => {
    this.isSidebarOpen = false;
    this.rerender();
    this.syncChildComponents();
  };

  private async loadSummary(): Promise<void> {
    this.isLoading = true;
    this.rerender();
    this.syncLoadingState();
    try {
      const allMetrics = Array.from(new Set(this.widgets.flatMap(w => w.metrics)));
      this.summary = await dashboardService.getDashboardSummary(this.currentPeriod, allMetrics);
    } catch {
      this.summary = null;
    }
    this.isLoading = false;
    this.rerender();
    this.syncChildComponents();
    this.dispatchSuggestionCheckpoint();
  }

  private handleSuggestionAccepted = async (event: Event): Promise<void> => {
    const ce = event as CustomEvent<{ suggestionId: string }>;
    if (!ce.detail) return;
    try {
      await suggestionService.acceptSuggestion(ce.detail.suggestionId);
      void this.loadSummary();
    } catch {
      // Suggestion acceptance is non-critical
    }
  };

  private dispatchSuggestionCheckpoint(): void {
    document.dispatchEvent(
      new CustomEvent('suggestion-checkpoint', {
        detail: { source: 'dashboard', entityType: 'campaign', clientId: 'client-1' },
        bubbles: true,
        composed: true,
      }),
    );
  }

  private syncLoadingState(): void {
    const loading = this.shadow.querySelector<LoadingStateHost>('loading-state');
    if (loading) {
      loading.variant = 'skeleton';
      loading.shape = 'chart';
    }
  }

  private syncChildComponents(): void {
    if (this.isLoading || !this.summary) return;
    
    this.widgets.forEach(w => {
      const chart = this.shadow.querySelector<ChartWidgetHost>(`chart-widget[data-id="${w.id}"]`);
      if (chart) {
        // Create unique data for the widget based on its selected metrics
        const scaleFactor = w.metrics.reduce((acc, m) => acc + m.length, 0) % 5 + 1;
        const offset = w.metrics.includes('Spend') ? 1.5 : w.metrics.includes('Clicks') ? 0.3 : 1;
        const modifiedData = this.summary!.chartData.map(point => ({
          label: point.label,
          value: point.value * scaleFactor * offset
        }));

        chart.data = modifiedData;
        chart.chartType = w.type;
        chart.format = 'currency';
        chart.isLoading = false;
      }
      const picker = this.shadow.querySelector<KpiMetricPickerHost>(`kpi-metric-picker[data-id="${w.id}"]`);
      if (picker) {
        picker.selectedMetrics = w.metrics;
        picker.deltas = this.summary!.deltas;
      }
    });

    if (this.isCompareModeOpen) {
      const comp1 = this.shadow.querySelector<ChartWidgetHost>('chart-widget[data-id="compare-1"]');
      const comp2 = this.shadow.querySelector<ChartWidgetHost>('chart-widget[data-id="compare-2"]');
      if (comp1 && comp2) {
        comp1.data = this.summary!.chartData;
        comp1.chartType = 'line';
        comp1.format = 'currency';
        comp1.isLoading = false;

        comp2.data = this.summary!.chartData.map(p => ({ label: p.label, value: p.value * 0.8 }));
        comp2.chartType = 'line';
        comp2.format = 'currency';
        comp2.isLoading = false;
      }
    }

    const period = this.shadow.querySelector<PeriodSelectorHost>('period-selector');
    if (period) {
      period.selectedPeriod = '7d';
    }
    
    const breakdownChart = this.shadow.querySelector<ChartWidgetHost>('.breakdown-chart');
    if (breakdownChart && this.activeShortcut) {
      breakdownChart.chartType = 'bar';
      breakdownChart.format = 'number';
      breakdownChart.isLoading = false;
      // Mock data based on selected tab to simulate different breakdown reports
      if (this.activeShortcut === 'OS') {
        breakdownChart.data = [
          { label: 'ANDROID', value: 450 },
          { label: 'IOS', value: 350 },
          { label: 'WINDOWS', value: 200 },
        ];
      } else if (this.activeShortcut === 'DAY') {
        breakdownChart.data = [
          { label: 'Mon', value: 120 }, { label: 'Tue', value: 180 }, { label: 'Wed', value: 150 },
        ];
      } else {
        breakdownChart.data = [
          { label: 'Segment A', value: 400 },
          { label: 'Segment B', value: 300 },
          { label: 'Segment C', value: 300 },
        ];
      }
    }

    const campaignsTable = this.shadow.querySelector<any>('.campaigns-table');
    if (campaignsTable) {
      campaignsTable.columns = [
        { key: 'name', label: 'Campaign', sortable: true },
        { key: 'status', label: 'Status', sortable: true, render: (r: any) => `<span style="font-weight: 600; color: ${r.status === 'Active' ? '#059669' : '#d97706'}">${r.status}</span>` },
        { key: 'spend', label: 'Spend', sortable: true, render: (r: any) => `$${r.spend.toLocaleString()}` },
        { key: 'impressions', label: 'Impressions', sortable: true, render: (r: any) => r.impressions.toLocaleString() },
        { key: 'cpa', label: 'eCPA', sortable: true, render: (r: any) => `$${r.cpa.toFixed(2)}` },
        { key: 'roas', label: 'ROAS', sortable: true, render: (r: any) => `${r.roas}x` },
      ];
      campaignsTable.rows = [
        { name: 'Holiday Promo 2024', status: 'Active', spend: 12500, impressions: 450000, cpa: 12.50, roas: 3.2 },
        { name: 'Retargeting EMEA', status: 'Active', spend: 8400, impressions: 320000, cpa: 8.90, roas: 4.5 },
        { name: 'Q3 Brand Awareness', status: 'Paused', spend: 45000, impressions: 1200000, cpa: 15.20, roas: 1.8 },
        { name: 'App Install Challenge', status: 'Active', spend: 3200, impressions: 85000, cpa: 4.50, roas: 5.1 },
        { name: 'Win-back Campaign', status: 'Active', spend: 1500, impressions: 25000, cpa: 22.00, roas: 2.1 },
      ];
      campaignsTable.totalItems = 5;
      campaignsTable.pageSize = 5;
      campaignsTable.searchPlaceholder = "Search campaigns...";
    }
  }

  private handlePeriodChanged = (event: Event): void => {
    const detail = (event as CustomEvent<DateRange>).detail;
    if (detail) {
      this.currentPeriod = detail;
      void this.loadSummary();
    }
  };

  private handleMetricsChanged = (event: Event): void => {
    const detail = (event as CustomEvent<string[]>).detail;
    const target = event.target as HTMLElement;
    const widgetId = target.getAttribute('data-id');
    if (widgetId) {
      const widget = this.widgets.find(w => w.id === widgetId);
      if (widget) {
        widget.metrics = detail;
        void this.loadSummary();
      }
    }
  };

  private handleClick = (event: Event): void => {
    const target = event.target as HTMLElement;

    if (target.closest('[data-action="add-widget"]')) {
      this.widgets.push({
        id: `widget-${Date.now()}`,
        type: 'bar',
        metrics: ['Impressions', 'Clicks']
      });
      this.rerender();
      this.syncChildComponents();
      return;
    }

    if (target.closest('[data-action="toggle-compare"]')) {
      this.isCompareModeOpen = !this.isCompareModeOpen;
      this.rerender();
      this.syncChildComponents();
      return;
    }

    if (target.closest('[data-action="close-compare"]')) {
      this.isCompareModeOpen = false;
      this.rerender();
      this.syncChildComponents();
      return;
    }

    const chartTypeBtn = target.closest('[data-chart-type]');
    if (chartTypeBtn) {
      const type = chartTypeBtn.getAttribute('data-chart-type') as 'bar' | 'line' | 'area';
      const widgetId = chartTypeBtn.closest('.chart-section')?.getAttribute('data-widget-id');
      if (type && widgetId) {
        const widget = this.widgets.find(w => w.id === widgetId);
        if (widget) {
          widget.type = type;
          const chart = this.shadow.querySelector<ChartWidgetHost>(`chart-widget[data-id="${widgetId}"]`);
          if (chart) chart.chartType = type;
          this.rerender();
        }
      }
    }
    
    if (target.closest('[data-action="toggle-sidebar"]')) {
      this.isSidebarOpen = !this.isSidebarOpen;
      this.rerender();
      this.syncChildComponents();
    }

    const shortcutBtn = target.closest('.shortcut-card');
    if (shortcutBtn) {
      const type = shortcutBtn.getAttribute('data-shortcut') as any;
      // Toggle off if already active, otherwise activate
      this.activeShortcut = this.activeShortcut === type ? null : type;
      this.rerender();
      this.syncChildComponents();
    }
  };

  private renderKpiCards(): string {
    if (!this.summary) return '';
    const metrics = ['Impressions', 'Clicks', 'Spend', 'Installs', 'Revenue', 'CTR', 'CPM', 'CPA', 'ROAS'];
    return metrics
      .map((m) => {
        const value = this.summary!.kpiValues[m] ?? 0;
        const delta = this.summary!.deltas[m];
        let deltaHtml = '';
        if (delta) {
          const arrow = delta.direction === 'up' ? '↑' : delta.direction === 'down' ? '↓' : '–';
          deltaHtml = `<span class="kpi-delta ${delta.direction}">${arrow} ${Math.abs(delta.value)}%</span>`;
        }
        let formatValue = value.toLocaleString();
        if (m === 'Spend' || m === 'Revenue' || m === 'CPM' || m === 'CPA') {
          formatValue = `$${value.toLocaleString()}`;
        } else if (m === 'CTR') {
          formatValue = `${value}%`;
        } else if (m === 'ROAS') {
          formatValue = `${value}x`;
        }
        
        return `<div class="kpi-card"><p class="kpi-label">${m}</p><div class="kpi-value-row"><span class="kpi-value">${formatValue}</span>${deltaHtml}</div></div>`;
      })
      .join('');
  }

  private renderShortcuts(): string {
    const tabs = [
      { id: 'DAY', label: 'P BY DAY' },
      { id: 'EXCHANGE', label: 'P BY EXCHANGE' },
      { id: 'OS', label: 'P BY OS' },
      { id: 'CAMPAIGN', label: 'P BY CAMPAIGN' },
      { id: 'CREATIVE', label: 'P BY CREATIVE' },
    ];
    const buttons = tabs.map(t => 
      `<button class="shortcut-card ${this.activeShortcut === t.id ? 'active' : ''}" data-shortcut="${t.id}" type="button">${t.label}</button>`
    ).join('');
    
    return `<div class="shortcuts-row">${buttons}</div>`;
  }
  
  private renderBreakdown(): string {
    if (!this.activeShortcut) return '';
    
    return `
      <div class="breakdown-section">
        <div class="breakdown-header">
          <select class="breakdown-filter">
            <option>FILTER ↓</option>
            <option>Impressions</option>
            <option>Spend</option>
          </select>
        </div>
        <div class="breakdown-chart-container">
          <chart-widget class="breakdown-chart"></chart-widget>
        </div>
      </div>
    `;
  }

  protected renderTemplate(): string {
    if (this.isLoading) {
      return html`
        <div class="dashboard-header">
          <h1 class="dashboard-title">Dashboard</h1>
        </div>
        <loading-state variant="skeleton" shape="chart"></loading-state>
      `;
    }

    if (!this.summary) {
      return html`
        <div class="dashboard-header">
          <h1 class="dashboard-title">Dashboard</h1>
        </div>
        <empty-state message="No dashboard data available"></empty-state>
      `;
    }

    return html`
      <div class="dashboard-content">
        <div class="dashboard-header">
          <h1 class="dashboard-title">Dashboard</h1>
          <div class="dashboard-controls">
            <button class="btn-outline" data-action="toggle-compare" type="button">Compare ▾</button>
            <period-selector></period-selector>
            <button class="btn-primary" data-action="add-widget" type="button">+ Add Widget</button>
          </div>
        </div>
        
        ${this.isCompareModeOpen ? SafeHtmlString.trusted(`
        <div class="compare-mode-section">
          <div class="compare-mode-header">
            <h2 class="compare-mode-title">Advanced Comparison Analysis</h2>
            <button class="compare-mode-close" data-action="close-compare" type="button">✖</button>
          </div>
          <div class="compare-charts-row">
            <div class="compare-chart-col">
              <div class="compare-config-bar">
                <h4 class="compare-config-title">Segment A</h4>
                <period-selector></period-selector>
                <select class="filter-select"><option>Campaign: All</option><option>Campaign 1</option></select>
                <select class="filter-select"><option>OS: All</option><option>iOS</option><option>Android</option></select>
              </div>
              <chart-widget data-id="compare-1"></chart-widget>
            </div>
            <div class="compare-chart-col">
              <div class="compare-config-bar">
                <h4 class="compare-config-title">Segment B</h4>
                <period-selector></period-selector>
                <select class="filter-select"><option>Campaign: All</option><option>Campaign 1</option></select>
                <select class="filter-select"><option>OS: All</option><option>iOS</option><option>Android</option></select>
              </div>
              <chart-widget data-id="compare-2"></chart-widget>
            </div>
          </div>
        </div>
        `) : ''}

        <div class="global-filters">
          <select class="filter-select"><option>Campaign: All</option><option>Campaign 1</option></select>
          <select class="filter-select"><option>Creative: All</option><option>Creative A</option></select>
          <select class="filter-select"><option>App Bundle: All</option></select>
          <select class="filter-select"><option>Publisher: All</option></select>
          <select class="filter-select"><option>Placement ID: All</option></select>
          <select class="filter-select"><option>Exchange: All</option></select>
          <select class="filter-select"><option>Ad Format: All</option></select>
          <select class="filter-select"><option>OS: All</option><option>iOS</option><option>Android</option></select>
        </div>

        <div class="kpi-scroll-container">${SafeHtmlString.trusted(this.renderKpiCards())}</div>
        <div class="insight-line">${this.summary.insight}</div>
        
        ${SafeHtmlString.trusted(this.widgets.map(w => `
        <div class="chart-section" data-widget-id="${w.id}">
          <div class="chart-header">
            <p class="chart-title">Performance Overview</p>
            <div class="chart-metric-selector">
              <kpi-metric-picker data-id="${w.id}"></kpi-metric-picker>
            </div>
            <div class="chart-type-toggle">
              <button class="chart-type-btn ${w.type === 'bar' ? 'active' : ''}" data-chart-type="bar" type="button">Bar</button>
              <button class="chart-type-btn ${w.type === 'line' ? 'active' : ''}" data-chart-type="line" type="button">Line</button>
              <button class="chart-type-btn ${w.type === 'area' ? 'active' : ''}" data-chart-type="area" type="button">Area</button>
            </div>
          </div>
          <chart-widget data-id="${w.id}"></chart-widget>
        </div>
        `).join(''))}
        
        ${SafeHtmlString.trusted(this.renderShortcuts())}
        ${SafeHtmlString.trusted(this.renderBreakdown())}

        <div class="campaigns-section">
          <h2 class="section-title">Best Performing Campaigns</h2>
          <data-table class="campaigns-table"></data-table>
        </div>
      </div>
      
      <button class="floating-ai-btn" data-action="toggle-sidebar" type="button" aria-label="Toggle AI Insights">AI</button>
      ${this.isSidebarOpen ? SafeHtmlString.trusted('<ai-suggestion-sidebar></ai-suggestion-sidebar>') : ''}
    `;
  }
}

ComponentRegistry.register('client-dashboard', DashboardPageElement);
export { DashboardPageElement };